"""Generate the research report from the sealed measurements."""
from collections import Counter
from statistics import mean,median
from run import HERE,read

def main():
    data=read(HERE/"results.json");r=data["all"];ks=r["k"]["2"];fs=ks["full_exact"];ds=ks["dynamic_exact"]
    byq=read(HERE/"outcomes.json"); size=[len(q["dyn_tree"]) for q in byq.values()]
    visits=[q["pair_only_visits"] for q in byq.values()]
    total=lambda k:sum(v[k] for v in ks["contrasts_by_question"])
    ro=read(HERE/"overflow-results.json")["pooled"]
    cf=read(HERE/"counterfactual-results.json")["rows"]
    resources=r["resources"];times=[a["s"] for a in resources if a["forwards"]==55]
    stock=read(HERE/"stock-probe.json")["rows"];checks=[x for a in stock.values() for x in a.values()]
    probe=max(x["max_pair_abs"] for x in checks)
    startup=read(HERE/"initial-cost.json")
    gold=r["qual"];stats=read(HERE/"theory-check.json")["stats"]
    co=read(HERE/"official-reference.json")["by_group"]["all"]
    count=Counter()
    for rec in cf.values():count.update({int(k):v for k,v in rec["histogram"].items()})
    sumarea=sum(row["areas"] for row in cf.values())
    retained=[row["scenarios"]["p020"]["no_change"] for row in cf.values()]
    maxerr=max(x["max_abs_error"] for row in cf.values() for x in row["scenarios"].values())
    lines=["# Нейронный поиск пары документов после отзыва источников","",
        "Исполнены обученные классификационные головы и DeBERTa-v3-large метода Beam Retrieval. Вопросы предварительно выбраны по хешу из HotpotQA distractor dev. Для каждого из восьми вопросов получили индивидуальные баллы 10 документов и 45 пар. Модель независимо вычисляет балл текста документа и вопроса, а затем условную оценку пары. При отзыве кандидатов меняется список двух первых живых документов. Пара участвует в повторном поиске, если содержит хотя бы один из них. [Beam Retrieval, NAACL](https://aclanthology.org/2024.naacl-long.96/) · [Авторские веса](https://github.com/canghongjian/beam_retriever/issues/1)","",
        "## До двух отзывов","",
        "| Метод | Фиксированные 45 пар, ровно два отзыва | Адаптивный beam=2, ровно два отзыва |",
        "|---|---:|---:|",
        f"| Полный пересчёт допустимых пар | {fs['all']}/360 | {ds['full_gated']}/360 |",
        f"| Обычный префикс при бюджете метода | {fs['top_matched']}/360 | {ds['raw_matched']}/360 |",
        f"| Известное взвешенное представительное семейство | {fs['linear']}/360 | — |",
        f"| Префикс пар, инцидентных четырём первым адресам, при равном числе строк | — | {ds['pool4_matched']}/360 |",
        f"| Все 30 пар, инцидентных этим четырём адресам | — | {ds['pool4']}/360 |",
        f"| Фильтрация первоначально раскрытых 17 пар | — | {ds['initial_pool_static']}/360 |",
        f"| Статическое дерево плюс проверка двух живых корней | {fs['tree']}/360 | {ds['static_tree_gated']}/360 |",
        f"| Дерево адаптивного поиска по документам победившей пары | — | {ds['pair_only_tree']}/360 |","",
        f"При адаптивном поиске хранили {min(size)}–{max(size)} пар, в среднем {mean(size):.2f}, плюс исходные четыре адреса первого шага. Ближайший контроль с тем же числом строк среди пар четырёх возможных корней дал 180/180 в первых четырёх вопросах и 174/180 в следующих четырёх. Дерево дало по 180/180. Шесть отличий сосредоточены в трёх вопросах. Поскольку все 45 пар уже были рассчитаны, далее указана только логическая стоимость построения. Построение посетило {min(visits)}–{max(visits)} состояний из 56. При двух отзывах фиксированный полный порядок и адаптивный поиск разошлись в {total('full_diff_dynamic')}/360 случаях. Удаление не задело начальную пару, но динамический ответ сменился в {total('initial_survives_but_dynamic_changes')}/360 случаях. Упорядоченный состав всех достижимых ответов проверен полным перебором. Для статического порядка известна конструкция представительных семейств. [Fomin et al.](https://arxiv.org/abs/1304.4626)","",
        "Изначально ветвление только по победителю было контрольной абляцией. После синтетических наблюдений получена лемма обмена. Она требует фиксированных порядков первой и второй ступеней и наличия победителя в промежуточных состояниях. При размере пары p и глубине f достаточно посетить не более суммы p^j для j от 0 до f. Каждая сохранённая пара достигается при некотором допустимом отзыве, что даёт нижнюю границу в модели явных строк. Проверка охватила 34 560 состояний всех порядков шести рёбер на четырёх вершинах для указанных B и f и 748 700 состояний на случайных порядках с 5–12 вершинами. [Доказательство и предпосылки](EXCHANGE_RU.md)","",
        "## За пределом гарантии","",
        "Сертификаты используют первые четыре адреса и сохранённые пары. Для раздельной проверки по корням каждое из двух направлений расширения получает верхнюю границу от одного из более ранних подмножеств. Для префикса оставляем столько же пар. У объединённого варианта дополнительный список явно увеличивает память.","",
        "| Отзывов | Состояний | Один общий сертификат | Раздельные пределы | Равный глобальный префикс | Объединение | Ошибок без проверки среди возвращённых |",
        "|---|---:|---:|---:|---:|---:|---:|"]
    for k in ("3","4"):
        a=ro[k];lines.append(f"| {k} | {a['events']} | {a['same_accepted']} | {a['per_root_accepted']} | {a['prefix_accepted']} | {a['union_accepted']} | {a['unchecked_accepted']-a['unchecked_correct']}/{a['unchecked_accepted']} |")
    lines += ["","Все сертифицированные ответы совпали с полным динамическим поиском. Раздельная проверка границ и один общий сертификат покрыли одинаковые запросы на этой панели. При неизвестном либо неподтверждённом результате нужен полный резерв. Внешняя задержка и частота подобных событий в работающем агенте не измерялись. [Протокол](OVERFLOW_RU.md)","",
        "## Минимальное изменение и вероятность результата","",
        f"Перечисление обязательных удалений и обязательных живых документов для каждой пары и возможного первого эшелона дало {sumarea} достижимых областей на восьми вопросах. Представление верно во всех 8 192 масках, включая случаи с единственным оставшимся документом или пустой базой. Проверены минимальные бюджеты для всех 360 пар. При независимом отзыве каждого документа с вероятностью 0,2 модельная вероятность сохранить начальную пару на этих примерах лежит между {min(retained):.4f} и {max(retained):.4f}. Для трёх однородных и одного неоднородного набора вероятностей максимальное расхождение формулы с суммированием по маскам составило {maxerr:.2g}. Эти вероятности заданы исследователем. Записи включают минимальную маску для каждой пары и области с вынужденными живыми и отозванными адресами. [Вывод и условия](COUNTERFACTUAL_RU.md)","",
        "Вероятностное ранжирование и объяснение результатов запросов через изменения исходных данных имеют длительную историю в исследованиях БД. Проверяемая здесь специализация использует совместные зависимости двухступенчатого читателя и факторизацию по множеству его первых живых документов. Универсальный приоритет этой конструкции над существующей литературой не установлен. [Soliman, Ilyas, Chang, ICDE](https://cs.uwaterloo.ca/~ilyas/papers/SolimanICDE2007.pdf) · [Meliou et al., PVLDB](https://www.vldb.org/pvldb/vol4/p34-meliou.pdf)","",
        "## Нейросеть, внешний ориентир и расходы","",
        f"На всех {co['questions']} вопросах исходные опубликованные пары авторов содержат оба размеченных документа в {co['both']} случаях ({100*co['both']/co['questions']:.2f}%). На нашей панели локальный исходный beam=2 совпал с эталоном в {gold['native_beam2_exact']}/8, полный поиск по 45 парам в {gold['full_exact']}/8. Совпадение локального beam=2 с опубликованными парами {gold['beam2_vs_authors']}/8. Индивидуальная разметка для сопоставления с нейронной панелью присоединялась после фиксации прогнозов. Во время фонового расчёта отдельно проверялось агрегированное качество публичных пар на полном dev. Изменения выдачи при отзыве в полном официальном dev эти восемь вопросов не оценивают. [Опубликованные прогнозы](https://github.com/canghongjian/beam_retriever/blob/902980bfb5bd47a963569ab9c3621fd5ae81204a/results/retrieval/hotpot_pred_best_retr.json)","",
        f"CPU FP32, {startup['model_parameters']:,} параметров, два потока. Семь стандартных полных прогонов по 55 encoder-вызовов занимали {min(times):.1f}–{max(times):.1f} с (медиана {median(times):.1f} с). Первый дополнительно включал 24 encoder-вызова для прямой проверки после одного отзыва. Максимальный рабочий набор основного процесса {max(e['max_rss_bytes'] for e in resources)/2**30:.2f} GiB. Один повтор запуска с локально доступными файлами потребовал {startup['end_to_end_seconds']:.2f} с до получения инициализированной модели. Страничный кэш ОС неконтролируем. В отдельной проверке исходная батчевая реализация на двух вопросах и двух сценариях сохранила составы пулов и все четыре результата. Максимальное расхождение отдельных logits {probe:.2g}. Расходы на исходное получение рангов входят в полную стоимость построения. Локальный кэш моделирует дальнейшие обращения после первичного чтения.","",
        "Оценки последствий отзыва парные внутри вопроса. Восемь вопросов (4+4) ограничивают вывод о частоте расхождений на всей коллекции. Метрика восстановления измеряет совпадение ранжирования, документный exact match измеряет выбор размеченной пары. Для утверждения о качестве ответа LLM нужны отдельный читатель и его оценка. [Протокол](PROTOCOL_RU.md) · [Числа по фиксированным группам и всем контролям](results.json) · [Воспроизведение](REPRODUCE_RU.md)"]
    (HERE/"REPORT_RU.md").write_text("\n".join(lines)+"\n",encoding="utf8")
if __name__=="__main__":main()
